begin;
set local search_path=public,extensions;
select plan(15);

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values
('a8400000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','manager-84@example.invalid','',now(),'{}','{}',now(),now()),
('a8400000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','viewer-84@example.invalid','',now(),'{}','{}',now(),now()),
('a8400000-0000-4000-8000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','technician-84@example.invalid','',now(),'{}','{}',now(),now()),
('a8400000-0000-4000-8000-000000000004','00000000-0000-0000-0000-000000000000','authenticated','authenticated','other-owner-84@example.invalid','',now(),'{}','{}',now(),now());
insert into public.organizations(id,legal_name,display_name,status,created_by)values
('b8400000-0000-4000-8000-000000000001','Assistance Roles One','Roles One','ACTIVE','a8400000-0000-4000-8000-000000000001'),
('b8400000-0000-4000-8000-000000000002','Assistance Roles Two','Roles Two','ACTIVE','a8400000-0000-4000-8000-000000000004');
insert into public.organization_memberships(id,organization_id,user_id,status,activated_at)values
('c8400000-0000-4000-8000-000000000001','b8400000-0000-4000-8000-000000000001','a8400000-0000-4000-8000-000000000001','ACTIVE',now()),
('c8400000-0000-4000-8000-000000000002','b8400000-0000-4000-8000-000000000001','a8400000-0000-4000-8000-000000000002','ACTIVE',now()),
('c8400000-0000-4000-8000-000000000003','b8400000-0000-4000-8000-000000000001','a8400000-0000-4000-8000-000000000003','ACTIVE',now()),
('c8400000-0000-4000-8000-000000000004','b8400000-0000-4000-8000-000000000002','a8400000-0000-4000-8000-000000000004','ACTIVE',now());
insert into public.organization_member_roles(membership_id,role_code,granted_by)values
('c8400000-0000-4000-8000-000000000001','CLIENT_ADMIN','a8400000-0000-4000-8000-000000000001'),
('c8400000-0000-4000-8000-000000000002','CLIENT_VIEWER','a8400000-0000-4000-8000-000000000001'),
('c8400000-0000-4000-8000-000000000003','PROVIDER_TECHNICIAN','a8400000-0000-4000-8000-000000000001'),
('c8400000-0000-4000-8000-000000000004','CLIENT_OWNER','a8400000-0000-4000-8000-000000000004');

create temporary table assistance_role_observed(key text primary key,value jsonb);grant select,insert on assistance_role_observed to authenticated;
set local role authenticated;select set_config('request.jwt.claim.sub','a8400000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a8400000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into assistance_role_observed values('manager_analysis',public.run_assisted_analysis('b8400000-0000-4000-8000-000000000001','CONTEXTUAL_ASSISTANT',null,'{}','{}','{}','a1000000-0000-4000-8000-000000000001',null,'role-manager-analysis','f8400000-0000-4000-8000-000000000001'));reset role;
select is((select value->>'outcome'from assistance_role_observed where key='manager_analysis'),'ASSISTANCE_PROPOSED','client manager can run assistance');

insert into public.assistance_suggestions(id,organization_id,request_id,suggestion_kind,target_type,score_basis_points,explanation_code,explanation)values('d8400000-0000-4000-8000-000000000001','b8400000-0000-4000-8000-000000000001',((select value->>'request_id'from assistance_role_observed where key='manager_analysis')::uuid),'CONTEXTUAL_GUIDANCE','PROFILE',5000,'ROLE_TEST_GUIDANCE','{"model_version":1,"evidence":{},"human_review_required":true}');
select throws_ok($$set local role authenticated;select set_config('request.jwt.claim.sub','a8400000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"a8400000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);select public.run_assisted_analysis('b8400000-0000-4000-8000-000000000001','CONTEXTUAL_ASSISTANT',null,'{}','{}','{}','a1000000-0000-4000-8000-000000000001',null,'role-viewer-analysis','f8400000-0000-4000-8000-000000000002')$$,'42501'::char(5),'ASSISTANCE_ACCESS_DENIED','same-organization client viewer cannot run assistance');
select throws_ok($$set local role authenticated;select set_config('request.jwt.claim.sub','a8400000-0000-4000-8000-000000000003',true);select set_config('request.jwt.claims','{"sub":"a8400000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);select public.run_assisted_analysis('b8400000-0000-4000-8000-000000000001','CONTEXTUAL_ASSISTANT',null,'{}','{}','{}','a1000000-0000-4000-8000-000000000001',null,'role-technician-analysis','f8400000-0000-4000-8000-000000000003')$$,'42501'::char(5),'ASSISTANCE_ACCESS_DENIED','same-organization provider technician cannot run client assistance');
select throws_ok($$set local role authenticated;select set_config('request.jwt.claim.sub','a8400000-0000-4000-8000-000000000004',true);select set_config('request.jwt.claims','{"sub":"a8400000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);select public.run_assisted_analysis('b8400000-0000-4000-8000-000000000001','CONTEXTUAL_ASSISTANT',null,'{}','{}','{}','a1000000-0000-4000-8000-000000000001',null,'role-cross-analysis','f8400000-0000-4000-8000-000000000004')$$,'42501'::char(5),'ASSISTANCE_ACCESS_DENIED','other-tenant owner cannot run assistance');
select throws_ok($$set local role authenticated;select set_config('request.jwt.claim.sub','a8400000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"a8400000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);select public.decide_assisted_suggestion('d8400000-0000-4000-8000-000000000001','ACCEPTED','Viewer forbidden','role-viewer-decision','f8400000-0000-4000-8000-000000000005')$$,'42501'::char(5),'ASSISTANCE_DECISION_DENIED','same-organization viewer cannot decide a suggestion');
select throws_ok($$set local role authenticated;select set_config('request.jwt.claim.sub','a8400000-0000-4000-8000-000000000003',true);select set_config('request.jwt.claims','{"sub":"a8400000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);select public.decide_assisted_suggestion('d8400000-0000-4000-8000-000000000001','ACCEPTED','Technician forbidden','role-technician-decision','f8400000-0000-4000-8000-000000000006')$$,'42501'::char(5),'ASSISTANCE_DECISION_DENIED','same-organization provider technician cannot decide a suggestion');
select throws_ok($$set local role authenticated;select set_config('request.jwt.claim.sub','a8400000-0000-4000-8000-000000000004',true);select set_config('request.jwt.claims','{"sub":"a8400000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);select public.decide_assisted_suggestion('d8400000-0000-4000-8000-000000000001','ACCEPTED','Cross tenant forbidden','role-cross-decision','f8400000-0000-4000-8000-000000000007')$$,'42501'::char(5),'ASSISTANCE_DECISION_DENIED','other-tenant owner cannot decide a suggestion');
set local role authenticated;select set_config('request.jwt.claim.sub','a8400000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a8400000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);insert into assistance_role_observed values('manager_decision',public.decide_assisted_suggestion('d8400000-0000-4000-8000-000000000001','ACCEPTED','Manager validated','role-manager-decision','f8400000-0000-4000-8000-000000000008'));reset role;
select is((select value->>'outcome'from assistance_role_observed where key='manager_decision'),'ASSISTANCE_SUGGESTION_ACCEPTED','client manager can decide a suggestion');

set local role authenticated;select set_config('request.jwt.claim.sub','a8400000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"a8400000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);insert into assistance_role_observed values('viewer_rows',jsonb_build_object('suggestions',(select count(id)from public.assistance_suggestions),'requests',(select count(id)from public.assistance_requests)));reset role;
select is((select value->>'suggestions'from assistance_role_observed where key='viewer_rows'),'0','same-organization viewer cannot read suggestions through RLS');
select is((select value->>'requests'from assistance_role_observed where key='viewer_rows'),'0','same-organization viewer cannot read assistance requests through RLS');
set local role authenticated;select set_config('request.jwt.claim.sub','a8400000-0000-4000-8000-000000000003',true);select set_config('request.jwt.claims','{"sub":"a8400000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);insert into assistance_role_observed values('technician_rows',jsonb_build_object('suggestions',(select count(id)from public.assistance_suggestions)));reset role;
select is((select value->>'suggestions'from assistance_role_observed where key='technician_rows'),'0','same-organization provider technician cannot read suggestions through RLS');
set local role authenticated;select set_config('request.jwt.claim.sub','a8400000-0000-4000-8000-000000000004',true);select set_config('request.jwt.claims','{"sub":"a8400000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2"}',true);insert into assistance_role_observed values('cross_rows',jsonb_build_object('suggestions',(select count(id)from public.assistance_suggestions)));reset role;
select is((select value->>'suggestions'from assistance_role_observed where key='cross_rows'),'0','other tenant cannot read suggestions through RLS');
set local role authenticated;select set_config('request.jwt.claim.sub','a8400000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a8400000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);insert into assistance_role_observed values('manager_rows',jsonb_build_object('suggestions',(select count(id)from public.assistance_suggestions),'requests',(select count(id)from public.assistance_requests)));reset role;
select is((select value->>'suggestions'from assistance_role_observed where key='manager_rows'),'1','client manager can read scoped suggestions');
select is((select value->>'requests'from assistance_role_observed where key='manager_rows'),'1','client manager can read scoped requests');
select ok((select p.prosrc like'%CLIENT_OWNER%CLIENT_ADMIN%CLIENT_BUYER%'and p.prosrc not like'%PROVIDER_TECHNICIAN%'and p.prosrc not like'%CLIENT_VIEWER%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='assistance_role_access'),'authorization helper contains explicit least-privilege role sets');

select * from finish();rollback;
